pub(crate) async fn new(
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    format: wgpu::TextureFormat,
) -> Result<Self, RenderStateError> {
    Self::new_with_texture_cache(
        device,
        queue,
        format,
        SharedDecodedTextureCache::default(),
    )
    .await
}

pub(crate) async fn new_with_texture_cache(
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    format: wgpu::TextureFormat,
    decoded_texture_cache: SharedDecodedTextureCache,
) -> Result<Self, RenderStateError> {
    let render = RenderState::new(device, queue, format).await?;
    let debug = DebugRenderState::new(device, &render.camera_bgl, format).await?;
    Ok(Self {
        render,
        debug,
        color_format: format,
        main_color_target: None,
        outline_targets: None,
        decoded_texture_cache,
        texture_uploads_remaining: usize::MAX,
        texture_uploads_pending: 0,
        texture_uploads_uploaded: 0,
        material_bind_group_cache: Default::default(),
    })
}
